import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static int n, K, mod;
    static int[][] f = new int[MAXN][20];
    static int[] countBits = new int[MAXN];
    static int[] maxPower = new int[MAXN];
    static int[] fact = new int[MAXN];
    static int[] invFact = new int[MAXN];

    static int fast_pow(int base, int exp) {
        long res = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * b) % mod;
            b = (b * b) % mod;
            e >>= 1;
        }
        return (int) res;
    }

    static int comb(int i, int j) {
        return (int) (((long) fact[i] * invFact[j] % mod) * invFact[i - j] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        if ((n & 1) == 1) {
            System.out.println(fast_pow(K, n));
            sc.close();
            return;
        }

        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }

        invFact[n] = fast_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 1; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }

        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    count++;
                }
            }
            countBits[i] = count;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    maxPower[i] = 1 << j;
                    break;
                }
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 20; j++) {
                f[i][j] = 0;
            }
        }
        f[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int remaining = i ^ maxPower[i];
            for (int mask = remaining; ; mask = (mask - 1) & remaining) {
                int current = mask + maxPower[i];
                int c2 = i ^ current;
                int limit = Math.min(K - 1, countBits[c2]);
                int tmp = comb(i, current);
                for (int j = 0; j <= limit; j++) {
                    f[i][j + 1] = (int) ((f[i][j + 1] + (long) f[c2][j] * tmp) % mod);
                }
                if (mask == 0) break;
            }
        }

        int total = 0;
        for (int j = 1; j <= Math.min(countBits[n], K); j++) {
            total = (int) ((total + (long) f[n][j] * comb(K, j) % mod * fact[j]) % mod);
        }

        total = (fast_pow(K, n) - total + mod) % mod;
        System.out.println(total);
        sc.close();
    }
}
